import pathlib,subprocess,json,base64
e=pathlib.Path('/home/zjh/trade-measurements/08_audit_decomposition');r=pathlib.Path('/home/zjh/XiangMu/TradeSystem-rebuild')
source=e/'response_drain_test.cpp';source.write_bytes(base64.b64decode(''))
results=[]
for label,s,b in [('baseline',r,pathlib.Path('/home/zjh/trade-measurements/07_e2e_latency/build-final')),('candidate',e/'response-candidate-source',e/'response-candidate-build')]:
 binary=e/('response_drain_test-'+label)
 cmd=['g++','-std=c++20','-O2','-Wall','-Wextra','-Werror','-Wpedantic','-pthread','-I'+str(s),'-I'+str(s/'exchange'),'-I'+str(s/'trading'),str(source),'-Wl,--start-group',str(b/'exchange/liblibexchange.a'),str(b/'trading/liblibtrading.a'),str(b/'common/liblibcommon.a'),'-Wl,--end-group','-o',str(binary)]
 compiled=subprocess.run(cmd,capture_output=True,text=True);(e/(label+'-drain-compile.txt')).write_text(compiled.stdout+compiled.stderr)
 if compiled.returncode:print(compiled.stderr);raise SystemExit(compiled.returncode)
 ran=subprocess.run([str(binary)],cwd=e,capture_output=True,text=True,timeout=30)
 results.append({'label':label,'exit_code':ran.returncode,'output':ran.stdout+ran.stderr});print(results[-1],flush=True)
(e/'drain-regression.json').write_text(json.dumps(results,indent=2))
assert results[0]['exit_code']!=0 and results[1]['exit_code']==0
